# Test 7: Using retry_with
@retry(stop=stop_after_attempt(3))
def fails5():
    raise RuntimeError("retry_with")

fails5_disabled = fails5.retry_with(enabled=False)
call_count2 = 0

@fails5_disabled
def inner():
    global call_count2
    call_count2 += 1
    raise RuntimeError("inner fail")

try:
    inner()
except RuntimeError as e:
    assert call_count2 == 1
    print("PASS: retry_with(enabled=False) works", file=sys.stderr)

